.rv-account .woocommerce-Addresses{display:grid;grid-template-columns:1fr 1fr;gap:1rem}
.rv-account .woocommerce-Addresses::before,.rv-account .woocommerce-Addresses::after{display:none}
.rv-account .woocommerce-Address{float:none!important;width:auto!important;border:1px solid var(--rv-line);border-radius:16px;padding:1.4rem!important}
.rv-account .woocommerce-Address-title{display:flex;justify-content:space-between;align-items:baseline;gap:1rem}
.rv-account .woocommerce-Address-title h2{font-size:1.1rem!important;margin:0!important}
.rv-account .woocommerce-Address-title{flex-wrap:wrap;margin-bottom:1rem}
.rv-account .woocommerce-Address-title a.edit{font-size:.82rem;font-weight:700;text-decoration:none;padding:.35rem .75rem;border:1.5px solid var(--rv-line);border-radius:8px;color:var(--rv-ink2)!important;white-space:nowrap}
.rv-account .woocommerce-Address-title a.edit:hover{border-color:var(--rv-o);color:var(--rv-o)!important}
.rv-account .woocommerce-Address address{font-style:normal;line-height:1.65;color:var(--rv-mut);margin:0}
.rv-account fieldset{border:1px solid var(--rv-line);border-radius:16px;padding:1.4rem!important;margin:1.4rem 0!important}
.rv-account legend{font-weight:800;padding:0 .5rem}
.rv-account .woocommerce-form-row--first,.rv-account .woocommerce-form-row--last,.rv-account .form-row-first,.rv-account .form-row-last{width:100%!important}
.rv-account .woocommerce-EditAccountForm .clear{display:none}
.rv-account .woocommerce-EditAccountForm>p:has(.woocommerce-Button),.rv-account .woocommerce-address-fields>p:has(.button){margin-top:1rem!important}
.rv-account em{font-size:.8rem;color:var(--rv-mut)}
/* perks band */
.rv-perks{margin-top:clamp(2rem,5vw,3.5rem)!important}
.rv-perks .rv-card{padding:1.6rem!important;display:grid;grid-template-columns:auto 1fr;gap:0 1rem;align-items:start}
.rv-perks .rv-card>*{margin:0!important}
.rv-perks .rv-card .wp-block-html,.rv-perks .rv-card>:first-child{grid-row:span 2}
.rv-perks .rv-card h3{margin:0 0 .3rem!important;font-size:1.05rem!important}
.rv-perks .rv-card p{font-size:.92rem}
.rv-demo{margin-top:1.4rem!important;text-align:center;font-size:.85rem;color:var(--rv-mut)}
@media (max-width:980px){.rv-account .u-columns.col2-set,.rv-account .woocommerce:has(.woocommerce-MyAccount-navigation){grid-template-columns:1fr}.rv-account .woocommerce-MyAccount-navigation{position:static}}
@media (max-width:600px){.rv-account .woocommerce-Addresses{grid-template-columns:1fr}}
/* dark */
html.rv-darkmode .rv-account :is(.u-columns .col-1,.u-columns .col-2,.woocommerce>form.woocommerce-form-login,.woocommerce-ResetPassword,.woocommerce-MyAccount-content){background:#1B2026;border-color:#2A3038!important}
html.rv-darkmode .rv-account :is(input.input-text,input[type=text],input[type=email],input[type=password],input[type=tel],select,textarea){background:#12161A!important;color:#E9EAE6!important;border-color:#2A3038!important}
html.rv-darkmode .rv-account .show-password-input{color:#9AA1AA;filter:invert(1)}
html.rv-darkmode .rv-account .woocommerce-MyAccount-navigation{background:#0A0C0F;border:1px solid #2A3038}
html.rv-darkmode .rv-account table.shop_table thead th{background:#20262D}
html.rv-darkmode .rv-account .woocommerce-error{background:#2A1614;border-color:#6B2F27;color:#F2B8AF}
html.rv-darkmode .rv-account .woocommerce-message{background:#12241B;border-color:#2E5D45;color:#A8DCC2}
html.rv-darkmode .rv-account .woocommerce-info{background:#24170F;border-color:#5C3420;color:#F2C9B0}

/* estimativa de preço — formulário Pedir peça */
.rv-estimate{margin:.25rem 0 1.25rem;padding:1rem 1.2rem;border:1px solid var(--rv-line);border-left:4px solid var(--rv-o);border-radius:12px;background:rgba(242,97,29,.06)}
.rv-estimate.is-empty{border-left-color:var(--rv-line);background:transparent}
.rv-estimate p{margin:0}
.rv-est-label{font-size:.75rem;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--rv-mut)}
.rv-est-value{font-size:clamp(1.5rem,4vw,1.9rem);font-weight:800;color:var(--rv-o);line-height:1.2;margin:.2rem 0 .15rem!important;font-variant-numeric:tabular-nums}
.rv-est-detail{font-size:.88rem;color:var(--rv-ink2)}
.rv-est-warn{font-size:.85rem;color:#B5470F;margin-top:.4rem!important}
html.rv-darkmode .rv-est-warn{color:var(--rv-o2)}
.rv-est-note{font-size:.8rem;color:var(--rv-mut);margin-top:.4rem!important}
.rv-estimate.is-empty .rv-est-note{margin-top:.25rem!important}
/* medidas em 3 campos (C × L × A) — formulário Pedir peça */
.rv-form .rv-dimsrow{grid-template-columns:3fr 1fr;align-items:end}
.rv-dims legend{padding:0}
.rv-dims-unit{font-weight:400;color:var(--rv-mut)}
.rv-dims-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:.6rem}
.rv-form .rv-dim{margin:0;font-weight:600;font-size:.78rem;color:var(--rv-mut)}
.rv-dim-field{position:relative;display:block;margin-top:.3rem}
.rv-form .rv-dim input{padding-right:2.6rem;-moz-appearance:textfield}
.rv-form .rv-dim input::-webkit-inner-spin-button,.rv-form .rv-dim input::-webkit-outer-spin-button{-webkit-appearance:none;margin:0}
.rv-dim-mm{position:absolute;right:.8rem;top:50%;transform:translateY(-50%);font-size:.8rem;color:var(--rv-mut);pointer-events:none}
@media (max-width:600px){.rv-form .rv-dimsrow{grid-template-columns:1fr}}
